Index: apps/desktop/src/main/agents.test.ts
===================================================================
--- apps/desktop/src/main/agents.test.ts	
+++ apps/desktop/src/main/agents.test.ts	
@@ -0,0 +1,194 @@
+import { DEFAULT_SETTINGS, type ApiSetup, type LlmClient, type Settings } from "@reqflow/core";
+import { describe, expect, it, vi } from "vitest";
+import { z } from "zod";
+import { createAgentServices, testSetup, type AgentDeps } from "./agents";
+
+const claude: ApiSetup = {
+  id: "claude",
+  name: "Team Claude",
+  provider: "anthropic",
+  baseUrl: "",
+  model: "claude-opus-5-5",
+  fastModel: "claude-haiku-5-5",
+  effort: "high",
+  temperature: 0.2,
+  maxParallel: 2,
+};
+const jev: ApiSetup = {
+  ...claude,
+  id: "jev",
+  name: "Jev",
+  provider: "jev",
+  model: "jev-latest",
+  fastModel: "",
+};
+
+function settings(
+  roles: Partial<Settings["agents"]["roles"]> = {},
+  setups = [claude, jev],
+): Settings {
+  return {
+    ...DEFAULT_SETTINGS,
+    llm: { ...DEFAULT_SETTINGS.llm, provider: "anthropic" },
+    agents: { setups, roles: { ...DEFAULT_SETTINGS.agents.roles, ...roles } },
+  };
+}
+
+function deps(
+  o: { keys?: Record<string, string>; fetch?: typeof fetch; seen?: unknown[] } = {},
+): AgentDeps {
+  const fake: LlmClient = {
+    generateObject: async (r) => {
+      o.seen?.push(r);
+      return {
+        object: r.schema.parse({ answers: { support: { probability: 0.8 } } }),
+        model: "default-model",
+      };
+    },
+    generateText: async (r) => {
+      o.seen?.push(r);
+      return { text: "OK", model: "default-model" };
+    },
+  };
+  return {
+    defaultLlm: async () => fake,
+    getKey: async (id) => o.keys?.[id] ?? null,
+    fetch: o.fetch,
+  };
+}
+
+const claudeAnswer = () =>
+  new Response(
+    JSON.stringify({
+      model: "claude-opus-5-5",
+      stop_reason: "end_turn",
+      content: [{ type: "text", text: '{"ok":true}' }],
+    }),
+  );
+
+describe("agent services", () => {
+  it("uses the default AI where no setup is assigned, thinking at medium unless told otherwise", async () => {
+    const seen: any[] = [];
+    const services = createAgentServices(settings(), deps({ seen }));
+    const { info, llm } = await services.writer("architect");
+    expect(info).toMatchObject({
+      setupId: "default",
+      setupName: "Default AI",
+      provider: "anthropic",
+    });
+    await llm.generateObject({ prompt: "p", schema: z.object({ answers: z.any() }) });
+    await llm.generateObject({
+      prompt: "p",
+      schema: z.object({ answers: z.any() }),
+      effort: "off",
+    });
+    expect(seen.map((r) => r.effort)).toEqual(["medium", "off"]);
+  });
+
+  it("builds a role's client from its setup and key, sharing the setup's limiter", async () => {
+    const fetch = vi.fn<typeof globalThis.fetch>(async () => claudeAnswer());
+    const services = createAgentServices(
+      settings({ architect: "claude", critic: "claude" }),
+      deps({ keys: { claude: "sk-test" }, fetch }),
+    );
+    const architect = await services.writer("architect");
+    expect(architect.info).toMatchObject({
+      setupId: "claude",
+      setupName: "Team Claude",
+      maxParallel: 2,
+    });
+    await architect.llm.generateObject({ prompt: "p", schema: z.object({ ok: z.boolean() }) });
+    const sent = JSON.parse(String(fetch.mock.calls[0]![1]!.body));
+    expect(sent.output_config.effort).toBe("high"); // the setup's own effort
+    expect((fetch.mock.calls[0]![1]!.headers as Record<string, string>)["x-api-key"]).toBe(
+      "sk-test",
+    );
+  });
+
+  it("explains what's wrong instead of failing later", async () => {
+    const noKey = createAgentServices(settings({ analyst: "claude" }), deps());
+    await expect(noKey.writer("analyst")).rejects.toThrow(
+      'API setup "Team Claude" has no API key. Add it in Settings → AI.',
+    );
+    const judgeOnly = createAgentServices(
+      settings({ critic: "jev" }),
+      deps({ keys: { jev: "k" } }),
+    );
+    await expect(judgeOnly.writer("critic")).rejects.toThrow(/can only be the judge/);
+    const gone = createAgentServices(settings({ synthesizer: "deleted" }), deps());
+    await expect(gone.writer("synthesizer")).rejects.toThrow(/no longer exists/);
+  });
+
+  it("lets TypeSafe Jev judge, and an LLM judge otherwise", async () => {
+    const fetch = vi.fn<typeof globalThis.fetch>(
+      async () =>
+        new Response(
+          JSON.stringify({
+            model: "jev-1.13.0",
+            answers: { support: { type: "noul", noul: 0.7 } },
+          }),
+        ),
+    );
+    const viaJev = await createAgentServices(
+      settings({ judge: "jev" }),
+      deps({ keys: { jev: "k" }, fetch }),
+    ).judge();
+    const res = await viaJev.decisions.decide({
+      state: "s",
+      questions: { support: { type: "noul", instructions: "i" } },
+    });
+    expect(res).toMatchObject({
+      model: "jev-1.13.0",
+      answers: { support: { type: "noul", value: 0.7 } },
+    });
+    expect(viaJev.info.provider).toBe("jev");
+
+    const viaLlm = await createAgentServices(settings(), deps()).judge();
+    const llmRes = await viaLlm.decisions.decide({
+      state: "s",
+      questions: { support: { type: "noul", instructions: "i" } },
+    });
+    expect(llmRes.answers.support).toEqual({ type: "noul", value: 0.8 });
+  });
+});
+
+describe("testing an API setup", () => {
+  it("reports success with the model and time, and failures in safe words", async () => {
+    const ok = await testSetup(settings(), "default", deps());
+    expect(ok).toMatchObject({ ok: true, model: "default-model" });
+    expect(ok.message).toMatch(/^Connected: default-model answered in \d+ ms\.$/);
+
+    const fetch = vi.fn<typeof globalThis.fetch>(
+      async () =>
+        new Response(
+          JSON.stringify({
+            type: "error",
+            error: { type: "authentication_error", message: "bad key sk-xyz" },
+          }),
+          {
+            status: 401,
+          },
+        ),
+    );
+    const denied = await testSetup(
+      settings(),
+      "claude",
+      deps({ keys: { claude: "sk-xyz" }, fetch }),
+    );
+    expect(denied.ok).toBe(false);
+    expect(denied.message).toBe("Anthropic request failed (HTTP 401, authentication_error)");
+
+    expect(
+      await testSetup(
+        settings([] as never, [{ ...claude, id: "m", provider: "mock" }]),
+        "m",
+        deps(),
+      ),
+    ).toMatchObject({
+      ok: true,
+      model: "offline",
+    });
+    expect((await testSetup(settings(), "missing", deps())).ok).toBe(false);
+    expect((await testSetup(settings(), "claude", deps())).message).toMatch(/no API key/);
+  });
+});

Index: apps/desktop/src/main/agents.ts
===================================================================
--- apps/desktop/src/main/agents.ts	
+++ apps/desktop/src/main/agents.ts	
@@ -0,0 +1,207 @@
+import {
+  AGENT_ROLE_INFO,
+  API_PROVIDER_INFO,
+  DEFAULT_SETUP,
+  type AgentModel,
+  type AgentServices,
+  type ApiSetup,
+  type LlmClient,
+  type ReasoningEffort,
+  type Settings,
+  type WriterRole,
+} from "@reqflow/core";
+import type { SetupTestResult } from "@reqflow/core/ipc";
+import { createJudgeClient, createSetupClient, Limiter, llmDecisionClient } from "@reqflow/llm";
+
+export interface AgentDeps {
+  /** The default AI (Settings → AI) with its key; throws a readable error when it can't be used. */
+  defaultLlm: (settings: Settings) => Promise<LlmClient>;
+  /** The stored key of an API setup (`setup:<id>` in the OS keychain), or null. */
+  getKey: (setupId: string) => Promise<string | null>;
+  fetch?: typeof fetch;
+}
+
+/** The default AI has no effort setting of its own: writing roles think at this level. */
+const DEFAULT_AI_EFFORT: ReasoningEffort = "medium";
+const DEFAULT_AI_PARALLEL = 4;
+
+function defaultInfo(settings: Settings): AgentModel {
+  return {
+    setupId: DEFAULT_SETUP,
+    setupName: "Default AI",
+    provider: settings.llm.provider,
+    model: settings.llm.model,
+    fastModel: settings.llm.fastModel,
+    maxParallel: DEFAULT_AI_PARALLEL,
+  };
+}
+
+function setupInfo(s: ApiSetup): AgentModel {
+  return {
+    setupId: s.id,
+    setupName: s.name,
+    provider: s.provider,
+    model: s.model,
+    fastModel: s.fastModel || s.model,
+    maxParallel: s.maxParallel,
+  };
+}
+
+/** Requests that name no effort get this one (the agents ask for less where speed matters). */
+function withEffort(llm: LlmClient, effort: ReasoningEffort): LlmClient {
+  return {
+    generateObject: (r) => llm.generateObject({ ...r, effort: r.effort ?? effort }),
+    generateText: (r) => llm.generateText({ ...r, effort: r.effort ?? effort }),
+  };
+}
+
+/**
+ * Resolves every agent role to its API setup (Settings → AI → Agents) for one block run.
+ * Roles that share a setup share one limiter, so its "parallel calls" setting holds overall.
+ */
+export function createAgentServices(settings: Settings, deps: AgentDeps): AgentServices {
+  const limiters = new Map<string, Limiter>();
+  const limiterOf = (s: ApiSetup) => {
+    let l = limiters.get(s.id);
+    if (!l) limiters.set(s.id, (l = new Limiter(s.maxParallel)));
+    return l;
+  };
+  const setupOf = (id: string) => {
+    const s = settings.agents.setups.find((x) => x.id === id);
+    if (!s)
+      throw new Error(
+        `The API setup "${id}" no longer exists. Pick another one in Settings → AI → Agents.`,
+      );
+    return s;
+  };
+  const keyOf = async (s: ApiSetup) => {
+    const key = (await deps.getKey(s.id)) ?? undefined;
+    if (API_PROVIDER_INFO[s.provider].needsKey && !key) {
+      throw new Error(`API setup "${s.name}" has no API key. Add it in Settings → AI.`);
+    }
+    return key;
+  };
+  return {
+    async writer(role: WriterRole) {
+      const id = settings.agents.roles[role];
+      if (id === DEFAULT_SETUP) {
+        return {
+          info: defaultInfo(settings),
+          llm: withEffort(await deps.defaultLlm(settings), DEFAULT_AI_EFFORT),
+        };
+      }
+      const s = setupOf(id);
+      if (!API_PROVIDER_INFO[s.provider].writes) {
+        throw new Error(
+          `"${s.name}" (${API_PROVIDER_INFO[s.provider].label}) can only be the judge. Pick another setup for the ${AGENT_ROLE_INFO[role].label.toLowerCase()} in Settings → AI.`,
+        );
+      }
+      const llm = createSetupClient(s, {
+        apiKey: await keyOf(s),
+        fetch: deps.fetch,
+        limiter: limiterOf(s),
+      });
+      return { info: setupInfo(s), llm };
+    },
+    async judge() {
+      const id = settings.agents.roles.judge;
+      if (id === DEFAULT_SETUP) {
+        return {
+          info: defaultInfo(settings),
+          decisions: llmDecisionClient(await deps.defaultLlm(settings)),
+        };
+      }
+      const s = setupOf(id);
+      return {
+        info: setupInfo(s),
+        decisions: createJudgeClient(s, {
+          apiKey: await keyOf(s),
+          fetch: deps.fetch,
+          limiter: limiterOf(s),
+        }),
+      };
+    },
+  };
+}
+
+/**
+ * One tiny request through a setup ("Test" in Settings → AI). Never throws: the result says what
+ * went wrong in words safe to show (provider errors never carry keys or response bodies).
+ */
+export async function testSetup(
+  settings: Settings,
+  setupId: string,
+  deps: AgentDeps,
+): Promise<SetupTestResult> {
+  const started = Date.now();
+  const ms = () => Date.now() - started;
+  const signal = AbortSignal.timeout(60_000);
+  try {
+    if (setupId === DEFAULT_SETUP) {
+      const res = await (
+        await deps.defaultLlm(settings)
+      ).generateText({
+        prompt: "Reply with the single word OK.",
+        maxTokens: 200,
+        signal,
+      });
+      return {
+        ok: true,
+        model: res.model,
+        ms: ms(),
+        message: `Connected: ${res.model} answered in ${ms()} ms.`,
+      };
+    }
+    const s = settings.agents.setups.find((x) => x.id === setupId);
+    if (!s)
+      return {
+        ok: false,
+        ms: 0,
+        message: "This API setup isn't saved yet. Try again in a moment.",
+      };
+    if (s.provider === "mock") {
+      return {
+        ok: true,
+        model: "offline",
+        ms: 0,
+        message: "Mock runs offline: nothing to connect to.",
+      };
+    }
+    const apiKey = (await deps.getKey(s.id)) ?? undefined;
+    if (s.provider === "jev") {
+      const res = await createJudgeClient(s, { apiKey, fetch: deps.fetch }).decide({
+        state: "The car has four doors and a large boot.",
+        questions: { check: { type: "noul", instructions: "The text describes a car." } },
+        signal,
+      });
+      return {
+        ok: true,
+        model: res.model,
+        ms: ms(),
+        message: `Connected: ${res.model} answered in ${ms()} ms.`,
+      };
+    }
+    const res = await createSetupClient(s, { apiKey, fetch: deps.fetch }).generateText({
+      prompt: "Reply with the single word OK.",
+      maxTokens: 200,
+      signal,
+    });
+    return {
+      ok: true,
+      model: res.model,
+      ms: ms(),
+      message: `Connected: ${res.model} answered in ${ms()} ms.`,
+    };
+  } catch (err) {
+    const timedOut = signal.aborted;
+    return {
+      ok: false,
+      ms: ms(),
+      message: timedOut
+        ? "No answer within 60 s."
+        : err instanceof Error
+          ? err.message
+          : String(err),
+    };
+  }
+}

Index: apps/desktop/src/main/eval-f70.ts
===================================================================
--- apps/desktop/src/main/eval-f70.ts	
+++ apps/desktop/src/main/eval-f70.ts	
@@ -0,0 +1,255 @@
+import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
+import { join, resolve } from "node:path";
+import readXlsxFile from "read-excel-file/node";
+import {
+  defaultBlockParams,
+  emptyPipelineData,
+  mergePipelineData,
+  type PipelineData,
+  type ReasoningTrace,
+  type Requirement,
+  type Settings,
+  type StoredFile,
+} from "@reqflow/core";
+import { createBlockRegistry } from "@reqflow/blocks";
+import type { BlockContext, CarEvidence } from "@reqflow/engine";
+import { createLlmClient } from "@reqflow/llm";
+import { createAgentServices } from "./agents";
+import { SecretsStore } from "./secrets";
+import { loadSettings } from "./settings-storage";
+
+/**
+ * `npm run eval:f70`: the Add to Car agents on BMW's F70 files, with the user's own Settings and
+ * keys, to tune them. BMW data is confidential and session logs are public, so the console gets
+ * numbers only. The requirements and the thought process go to `<outDir>/<timestamp>/`, which
+ * lives in data/raw/ (gitignored), for the user to read privately.
+ */
+
+const FEEDBACK = "F70_feedback_hackathon.xlsx";
+const SALES = "sales_volumes.xlsx";
+const STUDY = "F70_G60_G68_G70_customer_studies.xlsx";
+
+export function parseEvalArg(argv: string[]): string | null {
+  const arg = argv.find((a) => a.startsWith("--eval-f70="));
+  return arg ? resolve(arg.slice("--eval-f70=".length)) : null;
+}
+
+const print = (line: string) => console.log(`[eval] ${line}`);
+const pct = (n: number, of: number) => (of ? `${Math.round((100 * n) / of)} %` : "–");
+const mean = (xs: number[]) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : 0);
+const round = (n: number, d = 2) => Math.round(n * 10 ** d) / 10 ** d;
+function tally<T extends string>(xs: T[]): string {
+  const counts = new Map<string, number>();
+  for (const x of xs) counts.set(x, (counts.get(x) ?? 0) + 1);
+  return [...counts].map(([k, n]) => `${k} ${n}`).join(" · ") || "none";
+}
+
+export async function runEvalF70(
+  outDir: string,
+  o: { rawDir: string; dataDir: string; maxRequirements: number },
+): Promise<number> {
+  const missing = [FEEDBACK, SALES].filter((f) => !existsSync(join(o.rawDir, f)));
+  if (missing.length) {
+    print(`missing in data/raw: ${missing.join(", ")}`);
+    return 1;
+  }
+  const stored = new Map<string, StoredFile>();
+  const files = {
+    get: async (id: string) => {
+      const f = stored.get(id);
+      if (!f) throw new Error(`No file ${id}`);
+      return f;
+    },
+  };
+  const registry = createBlockRegistry();
+  const raw = registry.get("raw");
+  const quietCtx = (blockId: string): BlockContext =>
+    ({
+      runId: "run_evalf70",
+      blockId,
+      scope: settings.defaultScope,
+      settings,
+      files,
+      log: () => {},
+      progress: () => {},
+      audit: { record: async () => ({}) as never },
+      signal: new AbortController().signal,
+      resumed: false,
+    }) as unknown as BlockContext;
+  /** Every sheet of a workbook through the Raw block, merged into one stream. */
+  async function read(
+    name: string,
+    dataset: string,
+  ): Promise<{ data: PipelineData; sheets: number }> {
+    const bytes = new Uint8Array(readFileSync(join(o.rawDir, name)));
+    const id = `file_${stored.size + 1}`;
+    stored.set(id, { id, name, mimeType: "", bytes });
+    const sheets = await readXlsxFile(Buffer.from(bytes));
+    let data = emptyPipelineData();
+    for (const s of sheets) {
+      const params = {
+        ...defaultBlockParams("raw"),
+        dataset,
+        file: { fileId: id, name },
+        sheet: s.sheet,
+      };
+      const res = await raw.run({}, params, quietCtx(`raw-${dataset}`));
+      if (res.status === "ok" && res.outputs.out) data = mergePipelineData(data, res.outputs.out);
+    }
+    return { data, sheets: sheets.length };
+  }
+
+  const settings: Settings = loadSettings(o.dataDir);
+  const feedback = await read(FEEDBACK, "customer_feedback");
+  const sales = await read(SALES, "sales_volume");
+  const study = existsSync(join(o.rawDir, STUDY)) ? await read(STUDY, "customer_study") : null;
+  print(
+    `inputs: 1. Priority = feedback (${feedback.data.records.length} records) · Context 1 = sales volumes (${sales.data.records.length} records, ${sales.sheets} sheets)` +
+      (study ? ` · Context 2 = study, Auto (${study.data.records.length} records)` : ""),
+  );
+
+  const secrets = new SecretsStore(o.dataDir);
+  const agents = createAgentServices(settings, {
+    defaultLlm: async (s) => {
+      const apiKey =
+        s.llm.provider === "anthropic"
+          ? ((await secrets.getSecret("anthropic_api_key")) ?? undefined)
+          : undefined;
+      if (s.llm.provider === "anthropic" && !apiKey) {
+        throw new Error("The default AI (Anthropic) has no API key. Add it in Settings → AI.");
+      }
+      return createLlmClient(s.llm, { apiKey });
+    },
+    getKey: (id) => secrets.getSecret(`setup:${id}`),
+  });
+  for (const role of ["context", "analyst", "synthesizer", "architect", "critic"] as const) {
+    const { info } = await agents.writer(role);
+    print(
+      `${role}: ${info.setupName} · ${info.provider} · ${info.model}${role === "analyst" ? ` (fast: ${info.fastModel})` : ""}`,
+    );
+  }
+  const judge = await agents.judge();
+  print(`judge: ${judge.info.setupName} · ${judge.info.provider} · ${judge.info.model}`);
+
+  const added: { requirements: Requirement[]; evidence?: CarEvidence }[] = [];
+  const traces: ReasoningTrace[] = [];
+  const logs: string[] = [];
+  let shown = -1;
+  const ctx: BlockContext = {
+    ...quietCtx("car"),
+    agents,
+    llm: {
+      generateObject: async () => Promise.reject(new Error("unused")),
+      generateText: async () => Promise.reject(new Error("unused")),
+    },
+    web: null,
+    car: {
+      add: async (requirements, evidence) => void added.push({ requirements, evidence }),
+      nextSeq: async () => 1,
+      saveReasoning: async (t) => void traces.push(t),
+    },
+    log: (m) => void logs.push(m), // kept in the private output, never printed: it can name themes
+    progress: (fraction, message) => {
+      const step = Math.floor(fraction * 10);
+      if (step > shown) {
+        shown = step;
+        print(
+          `${Math.round(fraction * 100)} %${message && !/[“"]/.test(message) ? ` ${message}` : ""}`,
+        );
+      }
+    },
+  };
+  const inputs: Record<string, PipelineData> = { "in-0": feedback.data, "ctx-0": sales.data };
+  if (study) inputs["ctx-1"] = study.data;
+  const params = {
+    ...defaultBlockParams("add_to_car"),
+    priorities: 1,
+    contexts: study ? ["sales_volumes", "auto"] : ["sales_volumes"],
+    maxRequirements: o.maxRequirements,
+  };
+  const started = Date.now();
+  try {
+    await registry.get("add_to_car").run(inputs, params, ctx);
+  } catch (err) {
+    // Our own error messages carry counts and setup names, never data.
+    print(
+      `FAILED after ${Math.round((Date.now() - started) / 1000)} s: ${err instanceof Error ? err.message : String(err)}`,
+    );
+    return 1;
+  }
+
+  const requirements = added.flatMap((a) => a.requirements);
+  const evidence = added[0]?.evidence ?? {};
+  const trace = traces[0];
+  const runDir = join(outDir, new Date().toISOString().replace(/[:.]/g, "-"));
+  mkdirSync(runDir, { recursive: true });
+  writeFileSync(join(runDir, "requirements.json"), JSON.stringify(requirements, null, 2));
+  writeFileSync(join(runDir, "trace.json"), JSON.stringify(trace ?? null, null, 2));
+  writeFileSync(join(runDir, "evidence.json"), JSON.stringify(evidence, null, 2));
+  writeFileSync(join(runDir, "logs.txt"), logs.join("\n"));
+
+  // ── numbers only ─────────────────────────────────────────────────────────────────────────
+  for (const s of trace?.steps ?? []) {
+    print(
+      `step ${s.role}: ${s.stats.map((x) => `${x.label} ${x.value}`).join(" · ")} · ${s.calls} calls · ${round(s.durationMs / 1000, 1)} s · ${s.status}`,
+    );
+  }
+  print(
+    `requirements: ${requirements.length} · priority ${tally(requirements.map((r) => r.priority ?? "none"))} · evidence ${tally(requirements.map((r) => r.evidenceLevel))}`,
+  );
+  print(
