     .sort((a, b) => a.rank - b.rank || b.weight - a.weight);
   const eligible = ranked.filter(({ theme }) => {
     const ok =
       mentionsOf(theme.support) >= 2 ||
       theme.support.some((s) => s.upstream) ||
       theme.support.some((s) => isQuantitative(s.finding, prepared.sources));
