         let thinking = first.thinking;
         let architectModel = first.model;
         const review1 = (
           await ask(criticW, criticMeter, {
             system: criticSystem(setup),
             payload: { contract: CONTRACT.critic, ...base, draft },
             schema: ReviewAnswer,
